async () => {
  const data = await connecta.call("controlled.records", { count: 120 });
  const records = Array.isArray(data) ? data : (data.records || data.items || data.results);
  if (!Array.isArray(records)) throw new Error("Record array not found");
  const out = {};
  for (const record of records) {
    const group = record.group;
    if (!Object.prototype.hasOwnProperty.call(out, group)) out[group] = { count: 0, scoreSum: 0 };
    out[group].count += 1;
    out[group].scoreSum += record.score;
  }
  return { recordCount: records.length, groups: out, sampleKeys: records.length ? Object.keys(records[0]) : [] };
}

