async () => {
  const calls = await connecta.batch([
    { address: "builds.get_workflow_run", args: { runId: 9 } },
    { address: "documents.search_content", args: { query: "staged customer rollout" } }
  ]);
  const [run, search] = calls;
  if (!run.ok) throw new Error("workflow run lookup failed: " + run.error);
  if (!search.ok) throw new Error("document content search failed: " + search.error);
  return { workflowRun: run.data, launchPlanMatches: search.data.results };
}

